import type { MainNavMenuProps } from "./main-nav-menu.types";

import { forwardRef, useMemo } from "react";
import { ThemeProvider, useTheme } from "@theme";
import { Menu } from "@components/menu";
import { clsx } from "clsx";

import { createMainNavTheme } from "../main-nav/utils/create-main-nav-theme";

import { MainNavMenuItem } from "./subcomponents/main-nav-menu-item";
import { MainNavMenuInlineBadge } from "./subcomponents/main-nav-menu-inline-badge";
import { MainNavMenuClasses } from "./main-nav-menu.styles";
import { MainNavMenuContext } from "./hooks/use-main-nav-menu";

const MainNavMenuRoot = forwardRef(
  (
    { variant = "default", className, children, ...props }: MainNavMenuProps,
    ref: React.ForwardedRef<null>,
  ) => {
    const theme = useTheme();
    const mainNavTheme = useMemo(() => theme && createMainNavTheme(theme), [theme]);
    const variantProp = variant === "default" ? "mainNavMenu" : variant;
    const contextValue = useMemo(() => ({ styleSlots: props.styleSlots }), [props.styleSlots]);

    return (
      <ThemeProvider theme={mainNavTheme}>
        <MainNavMenuContext.Provider value={contextValue}>
          <Menu
            ref={ref}
            className={clsx(MainNavMenuClasses.root, className)}
            variant={variantProp}
            {...props}
          >
            {children}
          </Menu>
        </MainNavMenuContext.Provider>
      </ThemeProvider>
    );
  },
);

MainNavMenuRoot.displayName = "MainNavMenu";

export const MainNavMenu = Object.assign(MainNavMenuRoot, {
  Trigger: Menu.Trigger,
  Content: Menu.Content,
  Group: Menu.Group,
  Divider: Menu.Divider,
  Item: MainNavMenuItem,
  InlineBadge: MainNavMenuInlineBadge,
});

export default MainNavMenu;
